world_checks.check_employees_and_reporting_lines:
def check(world):
    state = world.state()
    employees = state.get("employees", [])
    if len(employees) < 20:
        return f"expected at least 20 employees, got {len(employees)}"
    emp_ids = {e["employee_id"] for e in employees}
    regions = {e["region"] for e in employees}
    for req_reg in ("US", "UK", "APAC"):
        if req_reg not in regions:
            return f"missing region {req_reg} in employees"
    for e in employees:
        if e["manager_id"] not in emp_ids:
            return f"employee {e['employee_id']} has manager {e['manager_id']} not in employee roster"
    return None

world_checks.check_leave_balances_and_requests:
def check(world):
    state = world.state()
    balances = state.get("leave_balances", [])
    if len(balances) < 30:
        return f"expected at least 30 leave balance records, got {len(balances)}"
    for b in balances:
        allocated = float(b["allocated_days"])
        used = float(b["used_days"])
        reserved = float(b["reserved_days"])
        avail = float(b["available_days"])
        if abs((used + reserved + avail) - allocated) > 0.01:
            return f"balance mismatch for {b.get('balance_id')}: {allocated} != {used} + {reserved} + {avail}"
    return None

world_checks.check_policies_and_holidays:
def check(world):
    state = world.state()
    policies = state.get("hr_policies", [])
    if len(policies) < 5:
        return f"expected at least 5 policy entries, got {len(policies)}"
    regions_with_policies = {p["region"] for p in policies}
    for r in ("US", "UK", "APAC"):
        if r not in regions_with_policies:
            return f"missing policy for region {r}"
    holidays = state.get("holiday_calendars", [])
    if len(holidays) < 10:
        return f"expected at least 10 holidays, got {len(holidays)}"
    return None
